import {intakeExamples,productAreas,buildIntakeCase,retrieveIntakeSources} from './intake.mjs';
import {productDetails,analyze,assignAutomatically,routeManually,summaryText,approveSummaryText,approveDraft,deliver,confirmHandoff,safeAudit,redact,categories,editOutput,adaptDevelopmentCase,developmentOptions} from './review-engine.mjs';
import {openEvaluation} from './evaluation-ui.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=async p=>{const r=await fetch(p);if(!r.ok)throw new Error('Could not load demo data.');return r.json();};
let originalData,developmentData,createdData,caseSet='original';
const datasetStates=new Map();
const receipts=new Map();
let cases,knowledge,history,current,activeTab='overview',aiTab='classification',filter='all',composeMode='note',timer;
let results=new Map(),events=new Map(),checkedSteps=new Map();
let options={failure:'none',low:false,responseLow:false,shadow:false,paused:false,noHistory:false},deliveryOutcome='acknowledged';
const reviewer='Alex Morgan';
const time=s=>new Date(s).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
function notify(s,error=false){clearTimeout(timer);$('#toast').textContent=s;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;timer=setTimeout(()=>$('#toast').hidden=true,5000);}
function modal(title,body){$('#modal').classList.toggle('evaluation-modal',title.includes('evaluation')||title.includes('Output review')); $('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal();}
function event(label,detail='',r=null,actor=reviewer){const list=events.get(current.id)||[];list.push({id:crypto.randomUUID(),at:new Date().toISOString(),label,detail,actor,audit:r?safeAudit(r,label,actor):null});events.set(current.id,list);}
function caseOptions(c=current){return {...options,failure:options.failure!=='none'?options.failure:c.dependencies?developmentOptions(c).failure:'none'};}
function prepare(c){if(c.createdInDemo)c.retrieval_fixture.candidate_source_ids=retrieveIntakeSources(c.conversation.filter(m=>m.author_role==='member').map(m=>m.text).join(' '),knowledge);const o=caseOptions(c);let r=assignAutomatically(analyze(c,knowledge,c.historyCandidateIds?history.filter(h=>c.historyCandidateIds.includes(h.id)):history,o),o);if(c.manualClassification){try{r=routeManually(r,c,knowledge,o,reviewer,c.manualClassification.category,c.manualClassification.reason);}catch{r.routingNotice='New compliance context requires specialist routing. Your earlier category override was not applied.';}}return r;}
function selectCase(id){current=cases.find(c=>c.id===id);activeTab='overview';aiTab='classification';$('#compose-text').value='';if(!results.has(id)){results.set(id,prepare(current));event('AI classified case','Category assigned automatically; no member message sent.',results.get(id),'AI simulation');}render();}
function renderList(){const q=$('#case-search').value.toLowerCase();const visible=cases.filter(c=>(filter!=='urgent'||c.priority==='P1'||c.priority==='P2')&&`${c.id} ${c.title} ${c.member.display_name}`.toLowerCase().includes(q));$('#case-count').textContent=visible.length;$('#case-list').innerHTML=visible.length?visible.map(c=>`<button class="case-item ${c.id===current.id?'active':''}" data-case="${c.id}" aria-pressed="${c.id===current.id}"><div class="case-item-top"><span>${c.id}</span><span class="priority ${c.priority.toLowerCase()}">${c.priority}</span></div><strong>${esc(c.title)}</strong><div class="case-item-bottom"><span>${esc(c.owner.name)}</span><span>${c.status==='resolved'?'Resolved':c.status==='investigating'?'Investigating':'Open'}</span></div></button>`).join(''):'<p class="empty-list">No matching cases.</p>';$('#case-list').querySelectorAll('button').forEach(b=>b.onclick=()=>selectCase(b.dataset.case));}
function renderCaseCategory(){const r=results.get(current.id);const category=r&&['accepted','assigned'].includes(r.classification.status)&&r.primaryCategory!=='unknown'?r.primaryCategory:'unassigned';$('#case-category').dataset.category=category;$('#case-category-value').textContent=categories[category]||'Unassigned';$('#case-category').title='Change category and routing';$('#case-category').setAttribute('aria-label','Change category: '+(categories[category]||'Unassigned'));}
function render(){if(!results.get(current.id)&&current.status!=='resolved'){const r=prepare(current);results.set(current.id,r);event('AI classification updated','Analysis updated automatically for the current case.',r,'AI simulation');}renderList();renderCaseCategory();$('#crumb').textContent=current.id;$('#case-key').textContent=current.id;$('#case-title').textContent=current.title;$('#case-status').value=current.status;$('#priority').textContent=current.priority+' priority';$('#priority').className='priority '+current.priority.toLowerCase();$('#owner').textContent=current.owner.name;$('#team').textContent=current.owner.team;$('#channel').textContent=current.createdInDemo?'Demo intake':'Web intake';$('#case-excerpt').textContent=current.conversation[0].text;$('#product-area').textContent=current.product_area;$('#case-product-area').textContent=current.product_area||'Unassigned';$('#case-version').textContent='Case version '+current.case_version;$('#member-name').textContent=current.member.display_name;$('#member-ref').textContent=current.member.permitted_profile.member_ref;$('#member-avatar').textContent=current.member.display_name.split(' ').map(x=>x[0]).join('');renderConversation();renderAI();renderIntakeStatus();renderActivity();renderEvidence();switchTab(activeTab);}
function renderConversation(){const all=[...current.conversation.map(m=>({...m,internal:false})),...current.internal_notes.map(n=>({...n,author_name:n.author,author_role:'Internal note',internal:true}))].sort((a,b)=>a.at.localeCompare(b.at));$('#message-count').textContent=current.conversation.length;$('#conversation').innerHTML=all.map(m=>`<article class="message ${m.internal?'internal':''}"><div class="message-head"><span><strong>${esc(m.author_name)}</strong><span class="role">${m.internal?'NOTE':m.author_role==='member'?'MEMBER':'SUPPORT'}</span></span><time>${time(m.at)}</time></div><p>${esc(m.text)}</p></article>`).join('');}
function historyCard(h){return `<details class="similar-card"><summary><span class="history-icon">↗</span><span class="history-main"><strong>${esc(h.title)}</strong><small>${esc(h.id)} · ${esc(h.why)}</small></span></summary><div class="history-detail"><p><b>Current report:</b> ${esc(h.currentReport)}</p><p><b>Previous report:</b> ${esc(h.sanitized_description)}</p><p><b>Differences to review:</b> ${esc(h.difference)}</p><p><b>Past handling:</b> ${esc(h.handling_outcome)}</p><p><b>Eligibility:</b> ${esc(h.eligibility)}</p><p><b>Current policy references:</b> ${Object.entries(h.policyVersions).map(([id,v])=>esc(id)+' v'+esc(v)).join(', ')}</p><p>Past handling does not establish facts or authorize a current action.</p></div></details>`;}
function reasonPrompt(title,fn){modal(title,`<label class="control-field">Reason<textarea id="review-reason" rows="4" placeholder="Explain the concern or correction…"></textarea></label><button id="reason-confirm" class="primary">Confirm manual assessment</button><p class="hint">This records a demo reviewer decision. No message is sent.</p>`);$('#reason-confirm').onclick=()=>{try{fn($('#review-reason').value);$('#modal').close();render();}catch(e){notify(e.message,true);}};}
function changeCategory(){
 const r=results.get(current.id);if(!r){notify('Reopen the case to change its category.');return;}
 modal('Change category & route',`<p class="modal-copy">Choose a category to update the case’s team. Any previous output approval will be cleared.</p><label class="control-field">Category<select id="route-category">${Object.entries(categories).map(([id,label])=>`<option value="${id}" ${r.primaryCategory===id?'selected':''} ${r.compliance&&id!=='compliance'?'disabled':''}>${id==='unknown'?'Unassigned':esc(label)} · ${id==='compliance'?'Compliance / Legal':id==='product_feedback'?'Product':'Customer Support'}</option>`).join('')}</select></label>${r.compliance?'<p class="hint">Compliance risk keeps this case in the specialist queue. Use Report incorrect to flag a mistake.</p>':''}<label class="control-field">Reason<textarea id="route-reason" rows="3" placeholder="Why are you changing the category or route?"></textarea></label><div class="modal-actions"><button id="save-route" class="primary">Update category & route</button></div>`);
 $('#save-route').onclick=()=>{try{const category=$('#route-category').value,reason=$('#route-reason').value;const next=routeManually(r,current,knowledge,caseOptions(),reviewer,category,reason);current.manualClassification={category,reason:redact(reason)};current.owner.team=next.destination;results.set(current.id,next);event('Category & route updated',`${categories[category]} → ${next.destination}`,next);$('#modal').close();render();notify('Case category and team updated.');}catch(e){notify(e.message,true);}};
}
function reportIncorrect(){reasonPrompt('Report incorrect classification',reason=>{if(!reason.trim())throw Error('Describe what is incorrect.');const r=results.get(current.id);current.classificationReports??=[];current.classificationReports.push({category:r?.primaryCategory,reason:redact(reason),at:new Date().toISOString(),reviewer});event('Incorrect classification reported','Agent flagged the category for review.',r);notify('Report recorded in this case. Use the category badge to change its route.');});$('#reason-confirm').textContent='Submit report';}
function renderAI(){
 const r=results.get(current.id),o=caseOptions();$('#ai-subtitle').textContent='Automatic classification · agent-approved next steps';
 if(!r){$('#ai-body').innerHTML='<p class="stale">Case resolved. Reopen it to continue with AI assistance.</p>';return;}
 const assigned=['assigned','accepted'].includes(r.classification.status)&&r.primaryCategory!=='unknown';
 const isDraft=typeof r.draft==='string',isProduct=r.primaryCategory==='product_feedback'&&!r.compliance,productTeam=productDetails(current).team;
 const approved=!!r.approval||!!r.summaryApproval,reports=current.classificationReports||[];
 let html=`<div class="ai-tabs" role="tablist" aria-label="AI assistance views"><button id="ai-classification-tab" role="tab" aria-controls="ai-classification-panel" aria-selected="${aiTab==='classification'}" data-ai-tab="classification" class="${aiTab==='classification'?'active':''}">Classification</button><button id="ai-next-tab" role="tab" aria-controls="ai-next-panel" aria-selected="${aiTab==='next'}" data-ai-tab="next" class="${aiTab==='next'?'active':''}">Next Steps</button></div>`;
 html+=`<section id="ai-classification-panel" role="tabpanel" aria-labelledby="ai-classification-tab" ${aiTab!=='classification'?'hidden':''}><div class="assigned-category"><span class="assignment-icon">${assigned?'✓':'—'}</span><div><span class="subtle">${r.classification.assignedBy==='AI simulation'?'Assigned by AI':'Case category'}</span><h3>${assigned?esc(categories[r.primaryCategory]):'Unassigned'}</h3><p>${esc(r.destination)}</p></div></div>`;
 if(!assigned)html+='<p class="classification-flag">Category needs attention. Select the category badge above to assign it manually.</p>';
 if(r.compliance)html+='<p class="classification-flag">Compliance flag · internal assistance only.</p>';
 if(r.routingNotice)html+=`<p class="classification-flag">${esc(r.routingNotice)}</p>`;
 if(reports.length)html+=`<div class="incorrect-report"><strong>Incorrect classification flagged</strong><p>${esc(reports.at(-1).reason)}</p><small>${reports.length} report${reports.length===1?'':'s'} recorded in this session</small></div>`;
 else html+='<p class="classification-clear">No classification mistakes reported.</p>';
 html+='<button id="report-incorrect" class="secondary">Report incorrect</button></section>';
 const text=isDraft?r.draft:summaryText(r.internalSummary),label=isDraft?'Email response draft':r.compliance?'Internal compliance summary':r.primaryCategory==='product_feedback'?'Internal Product summary':'Internal summary';
 html+=`<section id="ai-next-panel" role="tabpanel" aria-labelledby="ai-next-tab" ${aiTab!=='next'?'hidden':''}><label class="draft-label" for="next-step-text">${label}${approved?'<span>Approved</span>':''}</label><textarea id="next-step-text" class="draft concise-output" ${approved||r.execution?'readonly':''}>${esc(text)}</textarea><div class="concise-sources">Based on this conversation${r.sources.length?' · '+r.sources.slice(0,3).map(s=>`<button class="text-btn" data-source="${esc(s.id)}">${esc(s.id)} v${esc(s.version)}</button>`).join(' · '):' · no approved guidance available'}${r.similar.length?` · <button id="similar-evidence" class="text-btn">${r.similar.length} similar case${r.similar.length===1?'':'s'}</button>`:''}</div>`;
 if(o.paused||o.shadow||o.failure!=='none')html+=`<p class="hint">${o.paused?'Automation paused.':o.shadow?'Shadow mode: no sending or handoffs.':`${esc(o.failure)} unavailable; execution may require manual handling.`}</p>`;
 if(r.execution)html+=`<p class="outcome ${r.state==='held'?'warning':''}">${r.state==='held'?'Delivery outcome unknown. Reconcile before retrying.':r.state==='sent'?'Simulated response sent.':r.routedTeam?`Simulated handoff to ${esc(r.routedTeam)} acknowledged.`:'Simulated handoff acknowledged.'}</p>`;
 else if(isProduct&&r.action==='route')html+=`<button id="route-product" class="primary">Route to product team — ${esc(productTeam)}</button>`;
 else if(!approved)html+=`<button id="approve-next" class="primary">${isDraft?'Approve response':'Approve summary'}</button>`;
 else html+=`<div class="action-row">${isDraft?'<button id="send" class="primary">Send approved response</button>':r.action==='route'?'<button id="handoff" class="primary">Confirm handoff</button>':'<span class="review-receipt">Summary approved · continue handling the case</span>'}<button id="edit-output" class="text-btn">Edit</button></div>`;
 html+='</section>';$('#ai-body').innerHTML=html;
 $('#ai-body').querySelectorAll('[data-ai-tab]').forEach(b=>b.onclick=()=>{aiTab=b.dataset.aiTab;renderAI();});
 const panelTabs=[...$('#ai-body').querySelectorAll('[data-ai-tab]')];panelTabs.forEach((b,i)=>{b.tabIndex=b.dataset.aiTab===aiTab?0:-1;b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();aiTab=e.key==='Home'?'classification':e.key==='End'?'next':i===0?'next':'classification';renderAI();$(`[data-ai-tab="${aiTab}"]`).focus();}};});
 $('#report-incorrect').onclick=reportIncorrect;
 $('#ai-body').querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>showSource(b.dataset.source));
 if($('#similar-evidence'))$('#similar-evidence').onclick=()=>modal('Similar case evidence',`<p class="modal-copy">Past cases provide context; current policy controls this case’s next steps.</p>${r.similar.map(historyCard).join('')}`);
 $('#next-step-text').oninput=e=>{if(isDraft)r.draft=e.target.value;else r.internalSummary={text:e.target.value};};
 const save=(next,label)=>{results.set(current.id,next);event(label,'Review recorded against the current output.',next);};
 if($('#route-product'))$('#route-product').onclick=()=>{
  const reviewedText=$('#next-step-text').value;
  modal('Route to product team — '+productTeam,`<p class="modal-copy">Review this internal summary before routing to ${esc(productTeam)}. Team names are fictional demo ownership. This action approves the summary and confirms a simulated Product handoff.</p><pre class="json">${esc(reviewedText)}</pre><p class="hint">The summary stays in the restricted case. Only the existing sanitized handoff package is shared.</p><button id="confirm-product-route" class="primary">Confirm route to ${esc(productTeam)}</button>`);
  $('#confirm-product-route').onclick=()=>{try{const approvedResult=approveSummaryText(r,current,knowledge,o,reviewedText,reviewer);const next=confirmHandoff(approvedResult,current,knowledge,o,{ledger:receipts});save(next,'Product feedback routed to '+next.routedTeam);current.owner.team=next.routedTeam;$('#modal').close();render();notify('Simulated handoff to '+next.routedTeam+' confirmed.');}catch(e){notify(e.message,true);}};
 };
 if($('#approve-next'))$('#approve-next').onclick=()=>act(()=>save(isDraft?approveDraft(r,current,knowledge,o,$('#next-step-text').value,reviewer):approveSummaryText(r,current,knowledge,o,$('#next-step-text').value,reviewer),isDraft?'Member response approved':'Internal summary approved'));
 if($('#edit-output'))$('#edit-output').onclick=()=>act(()=>save(editOutput(r),'Output reopened for editing'));
 if($('#send'))$('#send').onclick=()=>act(()=>{save(deliver(r,current,knowledge,o,{outcome:deliveryOutcome,ledger:receipts}),'Simulated delivery outcome recorded');notify('Simulation only. No member was contacted.');});
 if($('#handoff'))$('#handoff').onclick=()=>{modal('Confirm specialist handoff',`<p class="modal-copy">Route to ${esc(r.destination)} with the restricted recipient package below. The internal summary stays in the case.</p><pre class="json">${esc(JSON.stringify(r.handoff,null,2))}</pre><button id="confirm-handoff" class="primary">Confirm handoff</button>`);$('#confirm-handoff').onclick=()=>{try{const next=confirmHandoff(r,current,knowledge,o,{ledger:receipts});save(next,'Simulated handoff acknowledged');current.owner.team=next.destination;$('#modal').close();render();}catch(e){notify(e.message,true);}};};
}
function act(fn){try{fn();render();}catch(e){notify(e.message,true);}}
function allEvents(){return [...current.timeline.map(e=>({at:e.at,label:({case_created:'Case created',owner_assigned:'Owner assigned',message_added:'Conversation updated',internal_note_added:'Internal note added'})[e.type]||e.type,detail:e.owner||e.message_ref||e.note_ref||'',actor:e.actor})),...(events.get(current.id)||[])].sort((a,b)=>b.at.localeCompare(a.at));}
function eventMarkup(e){return `<div class="event"><span class="event-dot"></span><div class="event-content"><strong>${esc(e.label)}</strong><small>${esc(e.actor)}${e.detail?' · '+esc(e.detail):''}</small></div><time>${time(e.at)}</time></div>`;}
function renderActivity(){const list=allEvents();$('#activity-count').textContent=list.length;$('#recent-events').innerHTML=list.slice(0,4).map(eventMarkup).join('');$('#activity-view').innerHTML=`<h2>Case activity</h2><p class="modal-copy">AI recommendations, human decisions, and execution outcomes appear alongside the existing case history.</p>${list.map(eventMarkup).join('')}`;}
function renderEvidence(){const ids=current.retrieval_fixture.candidate_source_ids;const sources=knowledge.filter(k=>ids.includes(k.id));$('#evidence-view').innerHTML=sources.length?sources.map(s=>`<article class="panel evidence-card"><div class="source-meta"><span>${s.id}</span><span>v${s.version}</span><span>${s.status==='approved'?'Approved in demo':'Retired · excluded'}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.content)}</p><p class="hint">Fictional source. Not official Bankrate policy.</p></article>`).join(''):'<div class="panel evidence-card"><h3>No applicable approved evidence</h3><p>Manual investigation is required. No missing guidance has been fabricated.</p></div>';}
function showSource(id){let s=knowledge.find(s=>s.id===id);modal(s.title,`<div class="source-modal"><span class="label-chip">${s.id} · v${s.version} · ${s.status}</span><p>${esc(s.content)}</p><p class="hint">Synthetic support guidance. It is not actual Bankrate policy.</p></div>`);}
function switchTab(tab){activeTab=tab;$('.tabs').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab);});$('#workspace').hidden=tab!=='overview';$('#workspace').style.display=tab==='overview'?'':'none';$('#activity-view').hidden=tab!=='activity';$('#evidence-view').hidden=tab!=='evidence';}
function controls(){modal('Demo controls',`<p class="modal-copy">Change a condition to automatically update the analysis. Prior output approvals are cleared. The existing case workflow remains available.</p><div class="control-grid"><label class="control-field">Dependency condition<select id="ctrl-failure">${[['none','All available'],['model','Model unavailable'],['knowledge','Knowledge unavailable'],['profile','Profile unavailable'],['ticketing','Ticketing unavailable'],['history','Similar-case retrieval unavailable']].map(([v,l])=>`<option value="${v}" ${options.failure===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="control-field">Simulated delivery result<select id="ctrl-delivery"><option value="acknowledged" ${deliveryOutcome==='acknowledged'?'selected':''}>Acknowledged</option><option value="unknown" ${deliveryOutcome==='unknown'?'selected':''}>Timeout · unknown outcome</option></select></label></div>${[['low','Low classification confidence'],['responseLow','Low response evidence support'],['noHistory','No historical cases available'],['shadow','Shadow mode — no execution'],['paused','Pause automation']].map(([id,label])=>`<label class="control-toggle"><input id="ctrl-${id}" type="checkbox" ${options[id]?'checked':''}>${label}</label>`).join('')}<div class="modal-actions"><button id="reset-controls" class="secondary">Reset controls</button><button id="apply-controls" class="primary">Apply conditions</button></div>`);$('#reset-controls').onclick=()=>{options={failure:'none',low:false,responseLow:false,shadow:false,paused:false,noHistory:false};deliveryOutcome='acknowledged';invalidateAll();$('#modal').close();};$('#apply-controls').onclick=()=>{options={failure:$('#ctrl-failure').value,low:$('#ctrl-low').checked,responseLow:$('#ctrl-responseLow').checked,noHistory:$('#ctrl-noHistory').checked,shadow:$('#ctrl-shadow').checked,paused:$('#ctrl-paused').checked};deliveryOutcome=$('#ctrl-delivery').value;invalidateAll();$('#modal').close();};}
function invalidateAll(){for(const [id,r] of results.entries())if(!r?.execution)results.set(id,null);event('Demo conditions changed','Previous decisions and approvals invalidated.');render();notify('Conditions updated. Analysis refreshed automatically.');}
async function dataReview(){if(caseSet==='created'){modal('Created cases',`<p class="modal-copy">${cases.length} case(s) created in this session. Submitted messages run through the same classification and output pipeline. These cases have no preassigned expected outcomes and are separate from the evaluation pack.</p>`);return;}if(caseSet==='development'){evaluation();return;}const expected=await get('data/expected-outcomes.json');const counts=expected.case_expectations.map(e=>{const c=cases.find(c=>c.id===e.case_id);const r=analyze(c,knowledge,history);return {e,c,r,pass:r.originalCategory===e.category&&!!r.draft===e.member_draft_allowed};});modal('Demo data & expected outcomes',`<div class="modal-copy"><p><strong>${counts.filter(x=>x.pass).length} / ${counts.length} category and drafting checks match the review labels.</strong><br>These finite synthetic cases do not establish production safety or the 80% resolution goal. Modified conversations may legitimately differ from the original labels.</p><p>24 case records · 14 sanitized historical cases · 11 source documents. Expected labels are loaded only for this review, independently of analysis.</p></div><table class="data-table"><thead><tr><th>Case</th><th>Scenario</th><th>Expected</th><th>Actual</th></tr></thead><tbody>${counts.map(x=>`<tr><td>${x.c.id}</td><td><button data-review-case="${x.c.id}">${esc(x.c.title)}</button></td><td>${esc(x.e.category)}</td><td><span class="${x.pass?'pass':'fail'}">${x.pass?'✓':'△'} ${esc(x.r.category)}</span></td></tr>`).join('')}</tbody></table>`);$('#modal-body').querySelectorAll('[data-review-case]').forEach(b=>b.onclick=()=>{const x=counts.find(x=>x.c.id===b.dataset.reviewCase);modal(x.c.id+' · Review details',`<div class="modal-copy"><p><strong>${esc(x.c.title)}</strong></p><p>Expected: ${esc(x.e.action)} → ${esc(x.e.destination)}<br>AI member draft: ${x.e.member_draft_allowed?'Eligible with approval':'Not permitted'}</p><p>${esc(x.e.rationale)}</p><p><strong>Actual similar cases:</strong> ${x.r.similar.map(h=>esc(h.id)).join(', ')||'No reliable match'}<br><strong>Expected relevant history:</strong> ${x.e.internal_ai_assistance?.expected_relevant_history_ids.join(', ')||'Not specified'}</p><p>Historical ranking is a simple topic-based demo. Inspect relevance and differences; it does not use the expected match list.</p></div><div class="modal-actions"><button class="primary" id="open-reviewed-case">Open this case</button></div>`);$('#open-reviewed-case').onclick=()=>{$('#modal').close();selectCase(x.c.id);};});}
function about(){modal('About this prototype',`<div class="modal-copy"><p>AI automatically assigns a category. Click the category badge to change the category and case team, or report an incorrect classification. Detected compliance risk retains specialist routing.</p><p>Next Steps contains a draft or editable internal summary. Approve the output, then separately confirm any simulated send or handoff. New conversation context updates the analysis and clears old approvals automatically. Manual categories persist unless new compliance context requires specialist routing.</p><p>Classification and generation use rules and templates, not a live model. All cases, policies, permissions, routing and delivery are fictional. State resets on reload.</p><p>Evaluation runs 30 development cases against independent labels. Real quality, privacy, permissions, durable recovery and business outcomes remain unproven. No real member is contacted.</p></div>`);}
function useDataset(data,type,id){
 if(cases)datasetStates.set(caseSet,{cases,knowledge,history,results,events,checkedSteps});
 caseSet=type;const saved=datasetStates.get(type);
 if(saved){({cases,knowledge,history,results,events,checkedSteps}=saved);}else{cases=type==='created'?data.cases:type==='original'?structuredClone(data.cases):data.cases.map(c=>({...adaptDevelopmentCase(c),title:c.conversation[0].text.slice(0,85),conversation:c.conversation.map(m=>({...m,author_name:m.author_role==='member'?'Synthetic member':'Support'}))}));knowledge=data.k;history=data.h;results=new Map();events=new Map();checkedSteps=new Map();}
 $('#dataset-mode').value=type;$('#case-search').value='';filter='all';$('.queue-filters').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));selectCase(id||cases[0].id);
}
function renderIntakeStatus(){const el=$('#intake-status');el.hidden=!current.createdInDemo;if(!current.createdInDemo)return;const r=results.get(current.id);el.textContent=r?`✓ Case received → ${r.classification.status==='unassigned'?'Category needs attention':categories[r.primaryCategory]} → ${r.draft?'Email draft ready':'Internal summary ready'}`:'Case received · resolved';}
function createCase(){
 modal('Create a case',`<label class="control-field">Prefill a test case<select id="intake-example"><option value="">Blank case</option>${intakeExamples.map(x=>`<option value="${x.id}">${esc(x.label)}</option>`).join('')}</select></label><form id="intake-form"><div class="control-grid"><label class="control-field">Member name<input id="intake-name" required maxlength="80" placeholder="Fictional member name" autocomplete="off"></label><label class="control-field">Product area<select id="intake-product">${productAreas.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label></div><label class="control-field">Subject<input id="intake-title" required maxlength="120" placeholder="What does the member need help with?"></label><label class="control-field">Member message<textarea id="intake-message" required maxlength="4000" rows="5" placeholder="Describe the request in the member’s own words…"></textarea></label><label class="control-field">Initial priority<select id="intake-priority"><option value="P3">P3 · Normal</option><option value="P2">P2 · High</option><option value="P1">P1 · Urgent</option></select></label><p class="hint">Simulation only. Created cases stay in this browser session; no email is sent.</p><div class="modal-actions"><button type="button" class="secondary" id="cancel-intake">Cancel</button><button type="submit" class="primary" id="submit-intake">Create case & run AI</button></div><p id="intake-error" role="alert" class="fail"></p></form>`);
 $('#intake-example').onchange=()=>{const sample=intakeExamples.find(x=>x.id===$('#intake-example').value);for(const key of ['name','title','message','product','priority'])$('#intake-'+key).value=sample?.[key]||(key==='product'?productAreas[0]:key==='priority'?'P3':'');$('#intake-error').textContent='';};
 $('#cancel-intake').onclick=()=>$('#modal').close();
 $('#intake-form').onsubmit=e=>{e.preventDefault();const button=$('#submit-intake');button.disabled=true;try{createdData??={cases:[],k:originalData.k,h:originalData.h};const fields=Object.fromEntries(['name','title','message','product','priority'].map(key=>[key,$('#intake-'+key).value]));const id='NEW-'+String(createdData.cases.length+1).padStart(3,'0');const c=buildIntakeCase(fields,{id,knowledge:createdData.k});createdData.cases.unshift(c);$('#dataset-mode option[value="created"]').disabled=false;$('#modal').close();useDataset(createdData,'created',id);event('AI output prepared',results.get(id).draft?'Complete email draft ready for review.':'Internal summary ready for review.',results.get(id),'AI simulation');aiTab='next';render();notify('Case created and classified. Your next step is ready to review.');}catch(error){$('#intake-error').textContent=error.message;button.disabled=false;}};
}
function evaluation(){openEvaluation({modal,notify,openCase:(data,id)=>{developmentData=data;useDataset(data,'development',id);}});}
$('#nav-create').onclick=createCase;$('#create-case').onclick=createCase;
$('#close-modal').onclick=()=>$('#modal').close();$('#case-category').onclick=changeCategory;$('#demo-controls').onclick=controls;$('#nav-data').onclick=dataReview;$('#nav-eval').onclick=evaluation;$('#dataset-mode').onchange=async()=>{if($('#dataset-mode').value==='original')useDataset(originalData,'original','INC-301');else if($('#dataset-mode').value==='created')useDataset(createdData,'created');else{if(!developmentData){const [c,k,h]=await Promise.all([get('eval-data/cases.json'),get('eval-data/sources.json'),get('eval-data/history.json')]);developmentData={cases:c.cases,k:k.articles,h:h.historical_cases};}useDataset(developmentData,'development');}};$('#nav-help').onclick=about;$('#limitations').onclick=about;$('#nav-cases').onclick=()=>switchTab('overview');$('#all-activity').onclick=()=>switchTab('activity');$('.tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('#case-search').oninput=renderList;$('.queue-filters').querySelectorAll('button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$('.queue-filters').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));renderList();});
$('#case-status').onchange=()=>{current.status=$('#case-status').value;event('Case status changed',current.status==='resolved'?'Manually resolved by reviewer; not counted as demonstrated AI resolution.':current.status);if(current.status==='resolved')results.set(current.id,null);render();};
function setCompose(mode){composeMode=mode;$('#note-mode').classList.toggle('active',mode==='note');$('#member-mode').classList.toggle('active',mode==='member');$('#compose-text').placeholder=mode==='note'?'Add context for your team…':'Write a fictional new member message…';$('#compose-hint').textContent=mode==='note'?'Visible to your team only':'Invalidates prior analysis and approval';$('#add-update').textContent=mode==='note'?'Add note':'Add update';}
$('#note-mode').onclick=()=>setCompose('note');$('#member-mode').onclick=()=>setCompose('member');$('#add-update').onclick=()=>{const text=$('#compose-text').value.trim();if(!text){notify('Write an update first.');return;}const at=new Date().toISOString();current.case_version++;current.updated_at=at;if(composeMode==='member'){current.conversation.push({id:`${current.id}-M${current.conversation.length+1}`,at,author_role:'member',author_name:current.member.display_name,text});event('Member update added','Previous analysis and approval invalidated.');}else{current.internal_notes.push({id:`${current.id}-N${current.internal_notes.length+1}`,at,author:reviewer,text});event('Internal note added','New case context requires refreshed analysis.');}results.set(current.id,null);$('#compose-text').value='';render();notify('Case updated. AI assistance refreshed automatically.');};
try{const [c,k,h]=await Promise.all([get('data/cases.json'),get('data/knowledge.json'),get('data/historical-cases.json')]);originalData={cases:c.cases,k:k.articles,h:h.historical_cases};useDataset(originalData,'original','INC-301');}catch(e){$('#ai-body').textContent=e.message;notify(e.message,true);}
